import{z as B,x as A,o as e,c as d,q as i,j as r,D as E,d as o,s,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"逻辑复制与 CDC","description":"","frontmatter":{"title":"逻辑复制与 CDC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/logical-replication-cdc.md","filePath":"cs/logical-replication-cdc.md","lastUpdated":1791063341000}'),p={name:"cs/logical-replication-cdc.md"};function c(D,a,C,m,S,h){const t=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="逻辑复制与-cdc" tabindex="-1">逻辑复制与 CDC <a class="header-anchor" href="#逻辑复制与-cdc" aria-label="Permalink to &quot;逻辑复制与 CDC&quot;">​</a></h1><div class="epigraph"><p>从 WAL 解出行级变化流：下游可异构、可过滤表。这是逻辑日志的消费者，不是备库再应用生理 redo。</p><footer>—— 据 Postgres logical decoding；Gray；CDC 实践；日志粒度课落地</footer></div><p><a href="/cs/backup-pitr">上一课</a>把 WAL 当 PITR 原料。本课把同一 WAL（或触发器）当成变化数据捕获（CDC）流。主干 <a href="/cs/replication-log">复制与日志传送</a> 偏物理。进阶：逻辑复制解码成 <code>INSERT/UPDATE/DELETE</code> 行像，给搜索索引、数仓、缓存。半同步下一课仍偏物理耐久。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理复制：同引擎、同版本、全库页。逻辑：表子集、转换、多下游。缺口是<strong>解码与槽</strong>：保持解码所需的 WAL 与旧行像（undo/堆版本），槽不消费则磁盘涨——与 MVCC 水位同一类钉子。顺序：事务提交序要在流里可见，否则下游聚合错。</p><p>全量+增量：先快照再从 LSN 接流，避免漏。DDL：逻辑流对模式演化敏感，迁移课的兼容窗口在此显现。</p><p><span class="marginnote">PostgreSQL logical decoding、MySQL binlog 行模式。Debezium 一类是生态。本课机制。无虚构论文号。</span></p><p><span class="marginnote">CDC（变化数据捕获）翻译一下：不再每天半夜全量导一遍表，而是像装了水表一样，把数据库的每一笔 INSERT/UPDATE/DELETE 变成一条流水记录，实时递给下游的搜索索引、缓存或数仓——「捕获」的就是这股持续的变化流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输出插件：把事务变化写成 JSON/protobuf。下游幂等：用 LSN 或主键+版本去重。恰好一次后课流系统再谈；库侧至少 at-least-once 加幂等键。</p><p>过滤：只发某些表，减少流量。大对象可跳过或另通道。</p><p><span class="marginnote">复制槽像小区报箱：下游宕机不消费，报（WAL）就全堆在报箱里——压垮的不是报箱而是磁盘。几百 GB 的库，几天滞留的 WAL 就能塞满剩余空间；所以「忘删槽会胀爆磁盘」是运维第一事故，不删不用的槽要当常态清理。</span></p>',12)),(e(),r(n,null,{default:E(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAL%5B%22%E7%94%9F%E7%90%86%20WAL%22%5D%20--%3E%20DEC%5B%22%E9%80%BB%E8%BE%91%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20SLOT%5B%22%E5%A4%8D%E5%88%B6%E6%A7%BD%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20SLOT%20--%3E%20DOWN%5B%22%E4%B8%8B%E6%B8%B8%E5%BC%82%E6%9E%84%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20DOWN%20--%3E%20ACK%5B%22%E6%8E%A8%E8%BF%9B%E6%A7%BD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[o("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"下游第一次接入怎么做到不漏不重？关键在把「快照」与「接流」在同一个 LSN 上对齐。",-1)),(e(),r(n,null,{default:E(()=>[s(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E5%BC%80%E5%A7%8B%EF%BC%9A%E8%AE%B0%E4%B8%8B%E5%BD%93%E5%89%8D%20LSN%22%5D%20--%3E%20SNAP%5B%22%E5%AF%B9%E8%A1%A8%E5%81%9A%E4%B8%80%E8%87%B4%E6%80%A7%E5%BF%AB%E7%85%A7%22%5D%0A%20%20SNAP%20--%3E%20SLOT%5B%22%E5%BB%BA%E5%A4%8D%E5%88%B6%E6%A7%BD%EF%BC%8C%E4%BB%8E%E8%AF%A5%20LSN%20%E8%B5%B7%E7%95%99%E5%AD%98%20WAL%22%5D%0A%20%20SLOT%20--%3E%20STREAM%5B%22%E5%BF%AB%E7%85%A7%E5%AE%8C%E6%88%90%E5%90%8E%E4%BB%8E%20LSN%20%E5%BC%80%E5%A7%8B%E6%B6%88%E8%B4%B9%22%5D%0A%20%20STREAM%20--%3E%20DEDUP%5B%22%E7%94%A8%E4%B8%BB%E9%94%AE%2B%E7%89%88%E6%9C%AC%E6%88%96%20LSN%20%E5%8E%BB%E9%87%8D%E9%87%8D%E5%8F%A0%E9%83%A8%E5%88%86%22%5D%0A%20%20DEDUP%20--%3E%20OK%5B%22%E5%BF%AB%E7%85%A7%E4%B8%8E%E5%A2%9E%E9%87%8F%E6%97%A0%E7%BC%9D%E8%A1%94%E6%8E%A5%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">初学者容易以为流里的变化是逐条实时发布的。实际按事务提交序发布：长事务跑一小时，它攒的一万条改动会憋到提交那刻才整包涌出——下游必须能承受这种突发，而不是假设流量永远平滑。</span></p><p>性能：解码 CPU、undo 读旧像。长事务一个大包提交时下游突发。与 SSI/锁无关直接，但未提交变化不应出现在流（按提交）。</p><p>冲突：多源写入下游要合并策略，本课单源。双向复制是另一事故源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲半同步 ACK。也不把 CDC 当 2PC。搜索引擎索引常用 CDC 填倒排。</p><p>后课默认：异构下游用逻辑 CDC+槽；同构 HA 用物理。半同步复制：提交等备库确认，换 RPO。</p><p>槽是消费者的 xmin，忘记 drop slot 会胀爆磁盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑复制从 WAL 解码行流，槽钉水位。</li><li>接流要快照对齐；DDL 要合同。</li><li>半同步复制下一课。</li><li>出处：logical decoding；Gray；CDC 实践。</li></ul>',9))])}const u=B(p,[["render",c]]);export{T as __pageData,u as default};
